-- ============================================================================
-- Smart Livestock Health — Production Data Import Script
-- Target: Render PostgreSQL Database (smart-livestock-db)
-- Safe & Idempotent: Uses ON CONFLICT DO NOTHING on every record
-- Preserves all foreign-key relationships, farmer accounts, livestock, and devices
-- ============================================================================

SET statement_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET client_min_messages = warning;
SET row_security = off;

BEGIN;

-- ----------------------------------------------------------------------------
