-- Table: sensor_telemetry (613 records)
-- ----------------------------------------------------------------------------

-- ----------------------------------------------------------------------------
-- Table: alerts (12 records)
-- ----------------------------------------------------------------------------

-- ----------------------------------------------------------------------------
-- Table: ai_assessments (613 records)
-- ----------------------------------------------------------------------------


COMMIT;

-- Verification Queries
SELECT 'users' as tbl, count(*) as count FROM public.users
UNION ALL
SELECT 'farms', count(*) FROM public.farms
UNION ALL
SELECT 'farm_memberships', count(*) FROM public.farm_memberships
UNION ALL
SELECT 'animals', count(*) FROM public.animals
UNION ALL
SELECT 'devices', count(*) FROM public.devices
UNION ALL
SELECT 'sensor_telemetry', count(*) FROM public.sensor_telemetry
UNION ALL
SELECT 'alerts', count(*) FROM public.alerts
UNION ALL
SELECT 'ai_assessments', count(*) FROM public.ai_assessments;
